'use strict';

const fs = require('node:fs');
const path = require('node:path');
const samples = require('./output-token-benchmark.json');
const { benchmarkRows, totals } = require('./lib/render-table');
const { pct } = require('./lib/rough-tokenizer');

const rows = benchmarkRows(samples);
const total = totals(rows);

const lines = [
  '<!-- Generated by `npm run bench:update`. Do not edit the table by hand. -->',
  '',
  '| Task | Normal | Dvader | Saved |',
  '|---|---:|---:|---:|',
  ...rows.map((row) => `| ${row.task} | ${row.normal} | ${row.dvader} | ${pct(row.saved)} |`),
  `| **Average** | **${total.normal}** | **${total.dvader}** | **${pct(total.saved)}** |`,
  '',
  `Measured average: **${pct(total.saved)} fewer rough output tokens** across ${rows.length} report-style coding tasks.`,
  '',
];

fs.writeFileSync(path.join(__dirname, 'README.generated.md'), lines.join('\n'));
